    return <NewspaperEmploymentVsHedgeFundOwnership2026Dashboard />;
  }

  if (type === "rural-hospital-closures-and-drive-times-2026") {
    return <RuralHospitalClosuresAndDriveTimes2026Dashboard />;
  }

  return null;
}

