"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  GEO_TIERS,
  HEADLINE,
  INCOME_BANDS,
  METRO_ROWS,
  NATIONAL_PATH,
  REGION_ROWS,
  SOURCE_NOTE,
  STATE_LADDER,
  burdenDelta,
  type Region,
} from "@/data/rent-burden-share-of-renter-income-2026-data";

type Panel = "ladder" | "vintage" | "path" | "income" | "geo";
type RegionFilter = "all" | Region;
type SortLens = "burden" | "severe" | "delta";

const COLORS = {
  burden: "#1d4ed8",
  severe: "#b91c1c",
  prior: "#94a3b8",
  path: "#0f766e",
  deltaPos: "#c2410c",
  deltaNeg: "#0f766e",
  pie: ["#1d4ed8", "#0f766e", "#c2410c", "#64748b"],
  region: {
    South: "#c2410c",
    West: "#1d4ed8",
    Northeast: "#7c3aed",
    Midwest: "#0f766e",
  } as Record<Region, string>,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

export function RentBurdenShareOfRenterIncome2026Dashboard() {
  const [panel, setPanel] = useState<Panel>("ladder");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [sortLens, setSortLens] = useState<SortLens>("burden");

  const filtered = useMemo(() => {
    return METRO_ROWS.filter((m) => (region === "all" ? true : m.region === region));
  }, [region]);

  const ladderData = useMemo(() => {
    const rows = filtered.map((m) => ({
      metro: m.metro.replace(", FL", "").replace(", CA", "").replace(", NV", "").replace(", LA", "").replace(", NY", "").replace(", MA", "").replace(", WA", "").replace(", GA", "").replace(", AZ", "").replace(", CO", "").replace(", TX", "").replace(", IL", "").replace(", PA", "").replace(", IA", "").replace(", KS", ""),
      full: m.metro,
      burden: m.burdenPct2023,
      severe: m.severePct2023,
      delta: burdenDelta(m),
      region: m.region,
    }));
    rows.sort((a, b) => {
      if (sortLens === "severe") return b.severe - a.severe;
      if (sortLens === "delta") return b.delta - a.delta;
      return b.burden - a.burden;
    });
    return rows;
  }, [filtered, sortLens]);

  const scatterData = useMemo(
    () =>
      filtered.map((m) => ({
        id: m.id,
        metro: m.metro,
        x: m.burdenPct2015,
        y: m.burdenPct2023,
        z: Math.max(40, Math.min(200, m.renterHhK / 8)),
        region: m.region,
        delta: burdenDelta(m),
      })),
    [filtered],
  );

  const pathData = useMemo(
    () =>
      NATIONAL_PATH.map((r) => ({
        year: String(r.year),
        burden: r.burdenPct,
        severe: r.severePct,
        households: r.burdenedM,
      })),
    [],
  );

  const incomeData = useMemo(
    () =>
      INCOME_BANDS.map((b) => ({
        band: b.band,
        moderate: Math.max(0, b.burdenPct - b.severePct),
        severe: b.severePct,
        total: b.burdenPct,
      })),
    [],
  );

  const regionDeltaData = useMemo(
    () =>
