          </p>
        </ChartCard>
      ) : null}

      {panel === "path" ? (
        <ChartCard
          title="National renter burden path"
          subtitle="ACS/JCHS series ?? 2020 omitted ?? area = burden share, line = severe share"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={pathData} margin={{ top: 8, right: 16, left: 4, bottom: 4 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis domain={[20, 55]} tick={{ fontSize: 11 }} unit="%" />
                <Tooltip
                  formatter={(v, name) => [
                    typeof v === "number" ? `${v}%` : String(v ?? ""),
                    String(name),
                  ]}
                />
                <Legend />
                <Area
                  type="monotone"
                  dataKey="burden"
                  name="Burden >30%"
                  fill={COLORS.path}
                  stroke={COLORS.path}
                  fillOpacity={0.25}
                />
                <Line
                  type="monotone"
                  dataKey="severe"
                  name="Severe >50%"
                  stroke={COLORS.severe}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "income" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
