                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="region" tick={{ fontSize: 11 }} />
                  <YAxis domain={[35, 55]} tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip
                    formatter={(v, name) => [
                      typeof v === "number" ? `${v}%` : String(v ?? ""),
                      String(name),
                    ]}
                  />
