    console.log("??? panel + region + kind + lens controls");

    await auditVizInteractions(page, { slug });
    console.log("??? rural-hospital-closures-and-drive-times-2026 QA passed");
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
